var n=`0186-saltimbocca-alla-romana`;var i=`world-0186`;var a=`IT`;var o=`southern-europe`;var s=4;var l=23;var r={en:`Saltimbocca alla Romana`,ua:`Сальтимбока по-римськи`};var u={en:`A classic dish from Italy, featuring veal cutlet, prosciutto crudo, sage. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Італія. Основні складники: теляча відбивна, прошуто крудо, шавлія. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var c=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 8 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 8 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:8,i:[[`veal-cutlet`,600,`g`],[`unsalted-butter`,50,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:5,i:[[`prosciutto-crudo`,140,`g`],[`sage`,20,`g`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 7 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 7 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:7,i:[[`dry-white-wine`,160,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`lemon-juice`,25,`ml`]]}];var g={slug:n,id:i,country:`IT`,region:o,servings:4,minutes:23,title:r,text:u,steps:c};export{a as country,g as default,i as id,l as minutes,o as region,s as servings,n as slug,c as steps,u as text,r as title};